using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool(Name = "fetch_post"), Description("Fetches a post by ID from the external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int postId,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var post = await client.GetFromJsonAsync<Post>(
            $"/posts/{postId}", cancellationToken);

        return post is null
            ? "Post not found."
            : $"Title: {post.Title}\n\nBody: {post.Body}";
    }

    private sealed record Post(int Id, int UserId, string Title, string Body);
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Summarizes the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional desired summary style (e.g. bullet-points, one-liner).")] string? style = null)
    {
        var systemInstruction = style is not null
            ? $"Summarize the following text using the '{style}' style. Be concise."
            : "Summarize the following text. Be concise.";

        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{systemInstruction}\n\n{text}" }
            }
        ];
    }
}

